import { default as ImageField } from "./image-field";
import { StoryObj } from "@storybook/react";
import { Form, FormField, buildField, useForm } from "../../../helpers/form-builder";

const meta = {
  title: "Primitives/Form Fields/ImageField",
  component: ImageField,
};

export default meta;

type Story = StoryObj<typeof meta>;

const initialForm: Form = {
  fields: new Map<string, FormField>().set(
    "image",
    buildField("image", {
      label: "Ansiktsbild för identifiering",
      type: "IMAGE_FIELD",
      helperText: "Du måste välja en tydlig ansiktsbild för att kunna identifieras vid entrén",
      isRequired: true,
      errorText: "Vänligen ladda upp en tydlig ansiktsbild (så att vi kan identifiera dig vid entrén)",
    }),
  ),
};

export const Primary: Omit<Story, "args"> = {
  render: function StoryComponent({ ...args }) {
    const [form, isFormvalid, handleFieldOnChange, setForm, validateForm] = useForm(initialForm);

    return <ImageField formField={form.fields.get("image")!} onUserChanged={handleFieldOnChange} />;
  },
};
